{"path":"assets/css/styles.css","content":"/* Glass morphism + sensory styling */
:root{
  --bg1:#0f1724;--glass:#ffffff22;--accent:#b08cff;--accent-2:#7dd3fc;--muted:#cbd5e1;--panel:#ffffff10;
  --radius:14px;--gap:20px;--maxw:1100px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6eef6;background:linear-gradient(180deg,#071023 0%,#0d1220 60%);
}
.bg-pattern{position:fixed;inset:0;z-index:0;background-image:url("assets/img/pattern.svg");background-size:1200px auto;opacity:0.12;filter:blur(8px)}
.container{max-width:var(--maxw);margin:0 auto;padding:36px 22px;position:relative;z-index:2}
.site-header{backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);padding:14px 0}
.site-header .container{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:#fff;text-decoration:none;margin-right:auto}
.nav{display:flex;gap:14px;align-items:center}
.nav a{color:var(--muted);text-decoration:none;font-size:0.95rem;padding:6px 10px;border-radius:10px}
.nav a.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#071023;font-weight:700}
#navToggle{display:none;background:transparent;border:0;color:#fff;font-size:20px}

.hero{padding:48px 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:24px;align-items:center}
.hero-copy h1{font-size:clamp(28px,4.5vw,44px);margin:0 0 10px;color:#fff}
.hero-copy .lead{color:var(--muted);margin:0 0 18px}
.hero-ctas{display:flex;gap:12px;margin-bottom:12px}
.btn{padding:10px 16px;border-radius:10px;text-decoration:none;display:inline-block}
.btn-primary{background:linear-gradient(90deg,var(--accent),#ffd1f2);color:#071023;font-weight:700}
.btn-outline{border:1px solid rgba(255,255,255,0.08);color:var(--muted)}
.quick-info{list-style:none;padding:0;margin:12px 0 0;color:var(--muted);font-size:0.9rem}
.hero-visual{display:flex;justify-content:center}
.calm-graphic{width:100%;height:auto;border-radius:12px;box-shadow:0 8px 30px rgba(2,6,23,0.6)}

.social-proof{margin-top:14px}
.testimonials{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.testimonials blockquote{background:var(--panel);padding:16px;border-radius:12px;color:var(--muted);font-style:italic}

.glass-panel{background:linear-gradient(135deg,rgba(255,255,255,0.03),rgba(255,255,255,0.02));border-radius:var(--radius);padding:22px;margin:22px 0;border:1px solid rgba(255,255,255,0.04);box-shadow:0 6px 30px rgba(3,6,23,0.6)}
.benefits .benefit-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;list-style:none;padding:0}
.benefit-grid li{background:transparent;padding:12px;border-radius:10px}
.process-steps{margin:12px 0;padding-left:18px}
.what-to-bring ul{margin:8px 0 12px}
.disclaimer{color:#ffd5d5;background:rgba(255,210,210,0.03);padding:8px;border-radius:8px}

.lead-form{display:flex;gap:8px;align-items:center}
.lead-form input{flex:1;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.06);background:transparent;color:#fff}
.form-note{color:var(--muted);font-size:0.85rem;margin-top:8px}

.faq details{background:var(--panel);padding:12px;border-radius:8px;margin-bottom:8px}
.faq summary{cursor:pointer;color:#fff}

.final-cta{display:flex;flex-direction:column;align-items:flex-start;gap:12px;padding:28px}
.cta-actions{display:flex;gap:12px}

.site-footer{color:var(--muted);padding:26px 0}
.foot-grid{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
.ripple{position:relative;overflow:hidden}
.ripple-svg{position:absolute;right:-10%;top:-10%;width:40%;height:40%;opacity:0.12;pointer-events:none}

@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr;}
  .testimonials{grid-template-columns:1fr}
  #navToggle{display:block}
  .nav{display:none}
}

/* small micro-interactions */
.btn-primary:active{transform:translateY(1px)}

"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // year
  var y = new Date().getFullYear();
  var ye = document.getElementById('year'); if(ye) ye.textContent = y;

  // mobile nav toggle
  var navToggle = document.getElementById('navToggle');
  navToggle && navToggle.addEventListener('click',function(){
    var nav = document.querySelector('.nav');
    if(!nav) return;
    if(nav.style.display==='flex'){nav.style.display='none';} else {nav.style.display='flex'; nav.style.flexDirection='column';}
  });

  // lead magnet form
  var lead = document.getElementById('leadForm');
  if(lead){
    lead.addEventListener('submit',function(e){
      e.preventDefault();
      var email = lead.querySelector('input[name="email"]').value;
      if(!email || email.indexOf('@')===-1){alert('Please enter a valid email');return}
      // faux submit - in real life hook to API
      lead.querySelector('button').disabled = true;
      lead.querySelector('button').textContent = 'Sending…';
      setTimeout(function(){
        lead.innerHTML = '<p class="sent">Thanks — check your inbox for the Starter Guide.</p>';
      },900);
    });
  }

  // simple testimonial rotator
  var blocks = document.querySelectorAll('.testimonials blockquote');
  if(blocks.length>1){
    var i=0; setInterval(function(){
      blocks.forEach(function(b,j){b.style.opacity = (j===i? '1':'0.18');b.style.transform=(j===i?'scale(1)':'scale(0.98)');});
      i=(i+1)%blocks.length;
    },4000);
  }

  // ripple subtle move
  var ripple = document.getElementById('ripple');
  document.addEventListener('mousemove',function(ev){
    if(!ripple) return;
    var x = (ev.clientX / window.innerWidth) * 100;
    var y = (ev.clientY / window.innerHeight) * 100;
    ripple.style.left = x + '%'; ripple.style.top = y + '%';
  });

});"} 
